import { Steps } from '@park-ui/react';
import { useState } from 'react';

const HorizontalStepper = () => {
  const [currentStep, setCurrentStep] = useState(0);
  const steps = [
    { title: 'Корзина', description: 'Проверьте товары' },
    { title: 'Доставка', description: 'Выберите адрес' },
    { title: 'Оплата', description: 'Способ оплаты' },
    { title: 'Подтверждение', description: 'Завершение заказа' }
  ];

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Steps.Root
        value={currentStep}
        onValueChange={(details) => setCurrentStep(details.value)}
        count={steps.length}
        orientation="horizontal"
      >
        <Steps.List>
          {steps.map((step, index) => (
            <Steps.Item key={index} index={index}>
              <Steps.Trigger>
                <Steps.Indicator />
                <Steps.Separator />
              </Steps.Trigger>
              <Steps.Content>
                <p className="font-medium">{step.title}</p>
                <p className="text-sm text-gray-500">{step.description}</p>
              </Steps.Content>
            </Steps.Item>
          ))}
        </Steps.List>
      </Steps.Root>

      <div className="mt-8 flex justify-between">
        <button
          onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
          disabled={currentStep === 0}
          className="px-4 py-2 border rounded-md disabled:opacity-50"
        >
          Назад
        </button>
        <button
          onClick={() => setCurrentStep(Math.min(steps.length - 1, currentStep + 1))}
          disabled={currentStep === steps.length - 1}
          className="px-4 py-2 bg-blue-600 text-white rounded-md disabled:opacity-50"
        >
          Далее
        </button>
      </div>
    </div>
  );
};
